def ensure_table(conn):
    conn.execute("CREATE TABLE IF NOT EXISTS journal_line (id INTEGER PRIMARY KEY, account TEXT, debit_minor TEXT, credit_minor TEXT)")


def create(conn, account, debit_minor, credit_minor):
    ensure_table(conn)
    cur = conn.execute("INSERT INTO journal_line(account, debit_minor, credit_minor) VALUES (?,?,?)", (account, debit_minor, credit_minor,))
    conn.commit()
    return cur.lastrowid


def get(conn, row_id):
    ensure_table(conn)
    return conn.execute("SELECT * FROM journal_line WHERE id=?", (row_id,)).fetchone()


def list_all(conn, limit=100):
    ensure_table(conn)
